-- "বাংলাদেশের সব দোকান" নয়, আমরা শুধু বিশ্বস্ত দোকানের দাম দেখাই; অ্যাডমিন নিজে লেখা বদলে থাকলে সেটা ছোঁয়া হয় না

update site_settings set value = jsonb_set(value, '{tagline}', to_jsonb('বিশ্বস্ত সব দোকানের দাম মিলিয়ে দেখুন, কেনার আগেই জানুন কোথায় সবচেয়ে কম।'::text)) where value ->> 'tagline' = 'বাংলাদেশের সব দোকানের দাম মিলিয়ে দেখুন, কেনার আগেই জানুন কোথায় সবচেয়ে কম।';
update site_settings set value = jsonb_set(value, '{taglineEn}', to_jsonb('Compare prices from trusted shops in Bangladesh and know where it''s cheapest before you buy.'::text)) where value ->> 'taglineEn' = 'Compare prices from shops across Bangladesh and know where it''s cheapest before you buy.';
update site_settings set value = jsonb_set(value, '{seoTitle}', to_jsonb('দরদাম – কম দাম কোথায়? বিশ্বস্ত সব দোকানের দাম এক জায়গায়'::text)) where value ->> 'seoTitle' = 'দরদাম – কম দাম কোথায়? এক ক্লিকে বাংলাদেশের সব দোকান';
update site_settings set value = jsonb_set(value, '{seoDescription}', to_jsonb('বাংলাদেশের বিশ্বস্ত দোকানগুলো থেকে একই পণ্যের দাম পাশাপাশি দেখুন — মোবাইল, ল্যাপটপ, গ্যাজেট থেকে শুরু করে আরও অনেক কিছু। কেনার আগে যাচাই করুন কোথায় সবচেয়ে কম।'::text)) where value ->> 'seoDescription' = 'বাংলাদেশের দোকানগুলো থেকে একই পণ্যের দাম পাশাপাশি দেখুন — মোবাইল, ল্যাপটপ, গ্যাজেট থেকে শুরু করে আরও অনেক কিছু। কেনার আগে যাচাই করুন কোথায় সবচেয়ে কম।';
update site_settings set value = jsonb_set(value, '{seoDescriptionEn}', to_jsonb('See the same product''s price from trusted shops in Bangladesh side by side — mobiles, laptops, gadgets and more. Check where it''s cheapest before you buy.'::text)) where value ->> 'seoDescriptionEn' = 'See the same product''s price from shops across Bangladesh side by side — mobiles, laptops, gadgets and more. Check where it''s cheapest before you buy.';
update site_settings set value = jsonb_set(value, '{heroTitleEn}', to_jsonb('See each shop''s price at a glance'::text)) where value ->> 'heroTitleEn' = 'See every shop''s price at a glance';
update site_settings set value = jsonb_set(value, '{heroEyebrow}', to_jsonb('বিশ্বস্ত সব দোকানের দাম, এক জায়গায়'::text)) where value ->> 'heroEyebrow' = 'বাংলাদেশের সব দোকানের দাম, এক জায়গায়';
update site_settings set value = jsonb_set(value, '{heroEyebrowEn}', to_jsonb('Prices from trusted shops in Bangladesh, in one place'::text)) where value ->> 'heroEyebrowEn' = 'Prices from every shop in Bangladesh, in one place';
